/**
 * Owns Seer's public lifetime-freshness predicate for hints, preflight and stage rechecks.
 * Inputs are read-only Seer data and actor/target IDs; output preserves the original
 * lifetime-history/self-target allowance. No cycle reset, resource write, current
 * permission capture or default installation occurs at this query boundary.
 * Before each existing hint/preflight/recheck, original field failures propagate;
 * failed or terminal windows remain their separate permission owners.
 * The public state accessor exposes only the same deeply readonly live slot;
 * installation and inspection writes remain in the feature state owner.
 * The named initialization binding keeps its original input-copy contract;
 * exposing that existing command grants no inspection or frame permission.
 */

import type { SeerReadState } from "@ai-werewolf-arena/game-contract";

export { getSeerState } from "./state";

export function seerTargetAllowed(
  state: SeerReadState | undefined,
  actorId: number,
  targetId: number,
): boolean {
  return (
    state?.targetPolicy !== "awa_fresh_others_v1" ||
    (targetId !== actorId && !state.history.some((row) => row.targetId === targetId))
  );
}

export { setSeerState } from "./state";

/**
 * Exposes Witch ordinary payload commands at their existing commit boundaries.
 * Inputs are selected read-only state/ability references after original rule checks; outputs
 * preserve reset, stock and flag writes in order. Callers retain permission and
 * effect ownership; failure never rolls back marks or prior consumed resources.
 * Independent audit ledgers and sealed native Demon stock do not call this port.
 * Native initialization keeps its existing named owner binding and copy behavior;
 * caller-supplied templates never gain a new live-resource write right.
 */
export {
  getWitchState,
  resetWitchNightState,
  refreshWitchSelfHeal,
  closeWitchPotionTurn,
  consumeWitchHeal,
  consumeWitchPoison,
  consumeRecipientPoison,
} from "./state";

export { setWitchState } from "./state";

/**
 * Defines the Hunter death-hook contribution for ordered death waves. Inputs are original
 * World players, death causes, shot choice and current-life context; outputs are pending
 * shot deaths and public Hunter events. The shared death-shot owner validates and consumes
 * the native gun at the existing accepted-shot boundary; poison produces its existing
 * silent event. Before an eligible shot, source/current-life permission checks belong to
 * the shared shot owner; failed or closed windows retain those checks. This hook never
 * opens a death permission, commits target death, advances phases or closes the wave.
 */
import { Role, permitsHunterShot } from "../../../../core/domain/model";
import type { DeathHook } from "../../hooks/hook_registry";
import { getHunterState } from "./state";
import { resolveDeathShots } from "../death_shot";

export const hunterDeathHook: DeathHook = (world, ids, sources, choose, events, context) =>
  resolveDeathShots(
    world,
    ids,
    sources,
    choose,
    events,
    {
      role: Role.Hunter,
      state: getHunterState,
      permits: (sources) => permitsHunterShot(sources),
      policy: (state) => state.deathActionPolicy ?? "awa_qualified_sources_v1",
      poisonEvent: (hunterId) => ({
        timestamp: Date.now(),
        type: "hunter_silent_due_to_poison",
        payload: { hunterId },
      }),
      shotEvent: (hunterId, targetId) => ({
        timestamp: Date.now(),
        type: "hunter_shot",
        payload: { hunterId, targetId },
      }),
    },
    context,
  );
